-- PostgreSQL (psql)
CREATE TABLE users (id int PRIMARY KEY, data jsonb);
INSERT INTO users VALUES (1, '{"plan": "free", "credits": 10}');
UPDATE users SET data = jsonb_set(data, '{plan}', '"pro"') WHERE id = 1;
CREATE INDEX idx_users_plan ON users ((data->>'plan'));
SELECT id, data->>'plan' AS plan, data->>'credits' AS credits FROM users;
